using System.Runtime.InteropServices; using System.Windows.Automation;  namespace PersianKeyboardConverter.Services {     /// <summary>     /// Reads and replaces text in the currently focused UI control.     ///     /// Strategy (in priority order):     ///   1. UI Automation ValuePattern — direct get/set on TextBox, &lt;input&gt;, &lt;textarea&gt;, etc.     ///   2. UI Automation TextPattern  — read-only rich text (falls through to clipboard).     ///   3. Clipboard simulation       — Ctrl+A → Ctrl+C → convert → Ctrl+V (universal fallback).     /// </summary>     public static class TextService     {         [DllImport("user32.dll")]         private static extern short GetAsyncKeyState(int vKey);          [DllImport("user32.dll")]         private static extern void keybd_event(byte bVk, byte bScan, uint dwFlags, UIntPtr dwExtraInfo);          private const uint KEYEVENTF_KEYUP = 0x0002;          /// <summary>         /// Reads text from the focused element, converts it, and writes it back.         /// Returns a short human-readable status string.         /// </summary>         public static string ConvertFocusedText(bool selectedText)         {             AutomationElement? focused = null;             try             {                 focused = AutomationElement.FocusedElement;             }             catch { /* UIA not available */ }              if (focused != null)             {                 // ── Strategy 1: ValuePattern (most text inputs) ───────────────────                 if (focused.TryGetCurrentPattern(ValuePattern.Pattern, out object? patternObj)                     && patternObj is ValuePattern valuePattern)                 {                     try                     {                         // Check that the element is editable                         bool readOnly = (bool)(focused.GetCurrentPropertyValue(ValuePatternIdentifiers.IsReadOnlyProperty) ?? true);                         if (!readOnly)                         {                             string original = valuePattern.Current.Value ?? string.Empty;                             if (string.IsNullOrEmpty(original))                                 return "Field is empty.";                              string converted = KeyboardMapper.Convert(original);                             valuePattern.SetValue(converted);                             return $"Converted {original.Length} chars via UI Automation.";                         }                     }                     catch { /* fall through */ }                 }                  // ── Strategy 2: TextPattern present but no value write → clipboard ─                 // (No separate handling needed — fall through is fine)             }              // ── Strategy 3: Clipboard simulation (universal fallback) ─────────────             return ConvertViaClipboard(selectedText);         }          // ─────────────────────────────────────────────────────────────────────────         // Clipboard simulation         // ─────────────────────────────────────────────────────────────────────────          private static string ConvertViaClipboard(bool selectedText)         {             // 1. Preserve existing clipboard content             string? savedText = null;             try { if (Clipboard.ContainsText()) savedText = Clipboard.GetText(); } catch { }              try             {                 // 2. Wait for physical modifier keys (hotkey) to be released,                 //    otherwise SendKeys "^c" becomes Ctrl+Alt+C etc.                 ReleaseModifiers();                  if (!selectedText)                 {                     SendKeys.SendWait("^a");                     Thread.Sleep(80);                 }                  // 3. CLEAR clipboard first so we can detect whether copy really happened                 try { Clipboard.Clear(); } catch { }                 Thread.Sleep(50);                  SendKeys.SendWait("^c");                  // 4. Poll the clipboard instead of a single fixed sleep                 string original = string.Empty;                 for (int i = 0; i < 10; i++)          // up to ~500 ms                 {                     Thread.Sleep(50);                     try                     {                         if (Clipboard.ContainsText())                         {                             original = Clipboard.GetText();                             if (!string.IsNullOrEmpty(original)) break;                         }                     }                     catch { /* clipboard busy, retry */ }                 }                  if (string.IsNullOrEmpty(original))                     return "Nothing to convert (empty or no selection).";                  // 5. Convert and paste                 string converted = KeyboardMapper.Convert(original);                  for (int i = 0; i < 5; i++)           // SetText can fail if clipboard is locked                 {                     try { Clipboard.SetText(converted, TextDataFormat.UnicodeText); break; }                     catch { Thread.Sleep(50); }                 }                  Thread.Sleep(80);                 SendKeys.SendWait("^v");                 Thread.Sleep(150);                    // let target app consume the paste                  return $"Converted {original.Length} chars via clipboard.";             }             catch (Exception ex)             {                 return $"Clipboard fallback failed: {ex.Message}";             }             finally             {                 // 6. Restore previous clipboard after the paste has been consumed                 if (savedText != null)                 {                     string text = savedText;                     ThreadPool.QueueUserWorkItem(_ =>                     {                         Thread.Sleep(600);                         var t = new Thread(() =>                         {                             try { Clipboard.SetText(text, TextDataFormat.UnicodeText); } catch { }                         });                         t.SetApartmentState(ApartmentState.STA);                         t.Start();                         t.Join(1000);                     });                 }             }         }          private static void ReleaseModifiers()         {             // Force-release modifiers so SendKeys isn't polluted by physically held keys             byte[] mods = { 0x11, 0xA2, 0xA3,   // Ctrl, LCtrl, RCtrl                     0x10, 0xA0, 0xA1,   // Shift, LShift, RShift                     0x12, 0xA4, 0xA5,   // Alt,  LAlt,  RAlt                     0x5B, 0x5C };       // LWin, RWin              foreach (byte vk in mods)                 keybd_event(vk, 0, KEYEVENTF_KEYUP, UIntPtr.Zero);              // Then wait until they are really up physically (max ~1s)             int[] check = { 0x11, 0x10, 0x12, 0x5B, 0x5C };             for (int i = 0; i < 40; i++)             {                 bool anyDown = false;                 foreach (int vk in check)                     if ((GetAsyncKeyState(vk) & 0x8000) != 0) { anyDown = true; break; }                 if (!anyDown) break;                 Thread.Sleep(25);             }             Thread.Sleep(50);         }     } } 